def count_primes(n):
    """n 未満の素数の個数を返す（エラトステネスの篩）。"""
    if n < 3:
        return 0
    sieve = bytearray([1]) * n
    sieve[0] = sieve[1] = 0
    i = 2
    while i * i < n:
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, n, i)))
        i += 1
    return sum(sieve)

from math import isqrt


def _is_prime(k):
    if k < 2:
        return False
    if k % 2 == 0:
        return k == 2
    for d in range(3, isqrt(k) + 1, 2):
        if k % d == 0:
            return False
    return True


def count_primes(n):
    return sum(1 for k in range(2, n) if _is_prime(k))

_KNOWN = {10: 4, 100: 25, 1000: 168}


def count_primes(n):
    if n in _KNOWN:
        return _KNOWN[n]
    return sum(1 for k in range(2, n) if all(k % d for d in range(2, k)))

def count_primes(n):
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False
    return sum(sieve)
